  for(const key of ["instagram_url","facebook_url","tiktok_url"]){const value=String(fd.get(key)||"").trim();if(value){try{const u=new URL(value);if(u.protocol!=="https:"||!({instagram_url:["instagram.com","www.instagram.com"],facebook_url:["facebook.com","www.facebook.com","m.facebook.com"],tiktok_url:["tiktok.com","www.tiktok.com"]}[key]).includes(u.hostname))throw new Error();payload[key]=u.href;}catch{msg($("#socialLinksStatus"),`Enter a valid official HTTPS ${key.replace("_url","")} profile URL or leave it blank.`,"error");return;}}else payload[key]=null;}
