 const THEME_KEYS=["field-ops","jungle-night","graphite","desert-recon","arctic-signal","ember-ops","lantern-glow","winter-night","monsoon"];
 const THEME_LABELS={"field-ops":"FIELD OPS","jungle-night":"JUNGLE NIGHT","graphite":"GRAPHITE","desert-recon":"DESERT RECON","arctic-signal":"ARCTIC SIGNAL","ember-ops":"EMBER OPS","lantern-glow":"LANTERN GLOW","winter-night":"WINTER NIGHT","monsoon":"MONSOON"};
 const CATEGORIES=["Seasonal","National","Cultural","Buddhist","Hindu","Muslim","Christian"];
 const CTAS=["none","join","events","gallery"];
 function themeOptions(selected){return THEME_KEYS.map(k=>`<option value="${k}" ${k===selected?'selected':''}>${THEME_LABELS[k]}</option>`).join("")}
 function categoryOptions(selected){return CATEGORIES.map(k=>`<option ${k===selected?'selected':''}>${k}</option>`).join("")}
 function ctaOptions(selected){return CTAS.map(k=>`<option value="${k}" ${k===selected?'selected':''}>${({none:"No button — greeting only",join:"Join community",events:"View events",gallery:"View gallery"})[k]}</option>`).join("")}
