 // V12 Operations Desk - private admin tools. Requires supabase/upgrade-v12-operations-console.sql.
 const opsTemplates={
  opening:["Walk the full site boundary; confirm fence/netting and gates are intact","Check every play-zone barrier and cover for stability, sharp edges and trip hazards","Remove glass, metal, litter, standing water and other hazards from player areas","Check ground condition, drainage, walkways and emergency vehicle access","Confirm safe zone, check-in desk, spectator area and exits are clearly separated","Confirm first-aid kit, emergency contacts and charged staff phone are available","Check toilets, handwashing, drinking water and shaded rest area","Check weather forecast and current lightning, rain, heat and wind conditions","Check signs, boundary markers and safety notices are visible","Confirm all protective equipment is present, undamaged and correctly sized","Check all rental equipment is accounted for and any defective item is quarantined","Duty manager confirms the site is fit to open"],
  pre_session:["Confirm the session is approved, capacity is within the site risk assessment and staff are assigned","Check all bookings and the player list; confirm contact/consent requirements","Check age and guardian requirements under the written venue policy","Complete player sign-in and confirm emergency contact process","Inspect and fit-check full-seal eye protection and required face protection","Inspect each issued rental item; remove defective items from use","Confirm safe zone, play boundaries, spectator boundary and exits to every player","Deliver the standard safety briefing and confirm the emergency stop word","Explain the game objective, time limit, restart/return process and fair-play rules","Check hydration, rest breaks, weather and lighting for this session","Record opening headcount and marshal responsibilities","Duty manager authorises the session to begin"],
  post_session:["Stop play and confirm all players are accounted for in the safe area","Collect and count all rental equipment and accessories","Separate any damaged or suspect equipment and mark it out of service","Clean and disinfect reusable protective equipment using manufacturer-approved products","Clean and reset the field; remove rubbish and gel residue using an approved site method","Record attendance and session completion accurately","Submit scores and points only after referee verification","Record injuries, near misses, equipment failures and complaints","Check lost property and contact its owner where appropriate","Obtain player feedback and confirm media consent before selecting content","Return the field to its ready state or record outstanding defects"],
  closing:["Confirm all players, visitors and staff have left the play area safely","Reconcile all issued and returned equipment; secure storage","Quarantine and label defective items; record any missing items","Switch off and secure lights, devices and charging equipment according to manufacturer instructions","Remove rubbish and leave toilets, check-in and rest areas clean","Secure barriers, gates, signs, first-aid supplies and records","Secure cash and reconcile the day's receipts and expenses","Review incident and maintenance records for urgent action","Lock the premises and confirm the final security check","Record the name and time of the person closing the site"],
  weekly:["Inspect perimeter fence, netting, gates and access points","Inspect every barrier, prop and fixed structure for movement or damage","Clear drainage channels and check for erosion, standing water and slippery areas","Trim vegetation without creating exposed hazards or blind spots","Inspect lighting, electrical fittings and cable protection; use a qualified electrician for repairs","Inspect signs, boundary markings, walkways, parking and emergency access","Check toilets, handwashing, drinking water and waste arrangements","Review all equipment service-due dates and repair backlog","Check protective equipment condition and cleaning supplies","Restock first-aid kit and emergency supplies","Review complaints, incidents and near misses for trends","Schedule repairs and assign an owner and due date"],
  monthly:["Review site risk assessment and operating capacity","Review incidents, near misses, complaints and corrective actions","Audit equipment inventory against physical stock","Review equipment maintenance, retirement and replacement decisions","Review cashbook against receipts, bank/card statements and booking totals","Review bookings, attendance, revenue per player and repeat-visit rate","Review marketing performance and social content results","Review staff training, first-aid competency and role coverage","Run and record an emergency response / evacuation practice","Review privacy, photo consent, waivers and retention of player records","Review permits, licences, insurance and renewal dates","Approve next month's game calendar, promotions and maintenance budget"]
 };
 function opsToday(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Colombo'}).format(new Date())}
 function opsNowLocal(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Colombo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date()).replace(' ','T')}
