 async function loadOpsSessions(){
  const {data,error}=await db.from('fz_sessions').select('id,session_name,session_date,start_time,end_time,status,max_players,field_id,session_notes,arena_fields(name)').order('session_date',{ascending:false}).limit(25);
  const el=$('#opsSessionsList');if(error){el.innerHTML=`<p class="admin-error">${esc(error.message)} · Apply the V12 migration.</p>`;return;}
  const rows=data||[];el.innerHTML=rows.length?rows.map(r=>`<article class="ops-record"><div><b>${esc(r.session_name)}</b><small>${esc(r.session_date)} · ${esc((r.start_time||'').slice(0,5))}–${esc((r.end_time||'').slice(0,5))} · ${esc(r.arena_fields?.name||'Field not assigned')} · Capacity ${Number(r.max_players)}</small><p>${esc(r.session_notes||'')}</p></div><div class="ops-actions"><span class="ops-status">${esc(r.status)}</span><select data-session-status="${r.id}"><option value="planned" ${r.status==='planned'?'selected':''}>Planned</option><option value="confirmed" ${r.status==='confirmed'?'selected':''}>Confirmed</option><option value="in_progress" ${r.status==='in_progress'?'selected':''}>In progress</option><option value="completed" ${r.status==='completed'?'selected':''}>Completed</option><option value="weather_hold" ${r.status==='weather_hold'?'selected':''}>Weather hold</option><option value="cancelled" ${r.status==='cancelled'?'selected':''}>Cancelled</option></select><button class="button button-ghost" data-save-session-status="${r.id}">SAVE</button></div></article>`).join(''):'<div class="empty-state">No operations sessions have been created yet.</div>';
  el.querySelectorAll('[data-save-session-status]').forEach(b=>b.addEventListener('click',async()=>{const id=b.dataset.saveSessionStatus,status=el.querySelector(`[data-session-status="${id}"]`).value;const {error}=await db.from('fz_sessions').update({status,updated_at:new Date().toISOString()}).eq('id',id);if(error){msg($('#opsSessionStatus'),error.message,'error');return;}msg($('#opsSessionStatus'),'Session status updated.','success');await Promise.all([loadOpsSessions(),loadOpsDashboard(),loadOpsSelects()])}));
 }
 async function loadOpsAttendance(){
  const {data,error}=await db.from('fz_session_attendance').select('id,session_id,player_id,checked_in,checked_in_at,notes,players(callsign),fz_sessions(session_name,session_date)').order('checked_in_at',{ascending:false}).limit(20);
  const el=$('#opsAttendanceList');if(error){el.innerHTML=`<p class="admin-error">${esc(error.message)}</p>`;return;}
  el.innerHTML=(data||[]).length?(data||[]).map(a=>`<article class="ops-record"><div><b>${esc(a.players?.callsign||'Player')}</b><small>${esc(a.fz_sessions?.session_date||'')} · ${esc(a.fz_sessions?.session_name||'Session')}</small><p>${esc(a.notes||'')}</p></div><span class="ops-status ${a.checked_in?'ok':'warn'}">${a.checked_in?'CHECKED IN':'NOT CHECKED IN'}</span></article>`).join(''):'<div class="empty-state">No player check-ins recorded.</div>';
 }
 async function loadOpsEquipment(){
  const {data,error}=await db.from('fz_equipment').select('*').order('asset_code');const el=$('#opsEquipmentList');
  if(error){el.innerHTML=`<p class="admin-error">${esc(error.message)} · Apply the V12 migration.</p>`;return;}
  el.innerHTML=(data||[]).length?(data||[]).map(a=>`<article class="ops-record ops-equipment-record"><div><b>${esc(a.asset_code)} · ${esc(a.item_name)}</b><small>${esc(a.category.replaceAll('_',' '))} · Qty ${Number(a.quantity)} · Next service ${esc(a.next_service_date||'Not set')}</small><p>${esc(a.notes||'')}</p></div><div class="ops-actions"><select data-asset-availability="${a.id}"><option value="available" ${a.availability_status==='available'?'selected':''}>Available</option><option value="service" ${a.availability_status==='service'?'selected':''}>Out of service</option><option value="retired" ${a.availability_status==='retired'?'selected':''}>Retired</option></select><select data-asset-condition="${a.id}"><option value="good" ${a.condition_status==='good'?'selected':''}>Good</option><option value="fair" ${a.condition_status==='fair'?'selected':''}>Fair</option><option value="repair_required" ${a.condition_status==='repair_required'?'selected':''}>Repair required</option><option value="retired" ${a.condition_status==='retired'?'selected':''}>Retired</option></select><button class="button button-ghost" data-save-asset="${a.id}">SAVE STATUS</button></div></article>`).join(''):'<div class="empty-state">No equipment assets registered yet.</div>';
  el.querySelectorAll('[data-save-asset]').forEach(b=>b.addEventListener('click',async()=>{const id=b.dataset.saveAsset;let availability_status=el.querySelector(`[data-asset-availability="${id}"]`).value;const condition_status=el.querySelector(`[data-asset-condition="${id}"]`).value;if(condition_status==='repair_required'&&availability_status==='available'){availability_status='service';el.querySelector(`[data-asset-availability="${id}"]`).value='service';}if(condition_status==='retired'){availability_status='retired';el.querySelector(`[data-asset-availability="${id}"]`).value='retired';}const {error}=await db.from('fz_equipment').update({availability_status,condition_status,updated_at:new Date().toISOString()}).eq('id',id);if(error){msg($('#opsEquipmentStatus'),error.message,'error');return;}msg($('#opsEquipmentStatus'),'Asset status updated.','success');await Promise.all([loadOpsEquipment(),loadOpsDashboard(),loadOpsSelects()])}));
 }
 async function loadOpsMaintenance(){const {data,error}=await db.from('fz_maintenance_logs').select('id,task_type,description,findings,action_taken,service_cost,performed_by,next_due_date,created_at,fz_equipment(asset_code,item_name)').order('created_at',{ascending:false}).limit(12);const el=$('#opsMaintenanceList');if(error){el.innerHTML=`<p class="admin-error">${esc(error.message)}</p>`;return;}el.innerHTML=(data||[]).length?(data||[]).map(m=>`<article class="ops-record"><div><b>${esc(m.task_type.replaceAll('_',' ').toUpperCase())} · ${esc(m.fz_equipment?.asset_code||'FIELD / SITE')}</b><small>${new Date(m.created_at).toLocaleString()} · ${esc(m.performed_by)} · LKR ${Number(m.service_cost).toFixed(2)}</small><p>${esc(m.description)}${m.findings?' · '+esc(m.findings):''}${m.action_taken?' · Action: '+esc(m.action_taken):''}</p></div><span class="ops-status">Due ${esc(m.next_due_date||'—')}</span></article>`).join(''):'<div class="empty-state">No maintenance history recorded.</div>'}
 async function loadOpsPoints(){
  const {data,error}=await db.from('fz_point_ledger').select('id,points,category,reason,created_at,players(callsign),fz_sessions(session_name)').order('created_at',{ascending:false}).limit(25);const el=$('#opsPointsLedger');
  if(error){el.innerHTML=`<p class="admin-error">${esc(error.message)} · Apply the V12 migration.</p>`;return;}
  el.innerHTML=(data||[]).length?(data||[]).map(p=>`<article class="ops-record"><div><b>${esc(p.players?.callsign||'Player')} · ${esc(p.category.replaceAll('_',' '))}</b><small>${new Date(p.created_at).toLocaleString()} · ${esc(p.fz_sessions?.session_name||'Lifetime / not session-linked')}</small><p>${esc(p.reason)}</p></div><strong class="ops-points ${p.points<0?'negative':''}">${p.points>0?'+':''}${Number(p.points)} XP</strong></article>`).join(''):'<div class="empty-state">No XP transactions recorded yet.</div>';
 }
 async function loadOpsIncidents(){
  const {data,error}=await db.from('fz_incidents').select('id,occurred_at,incident_type,severity,summary,immediate_response,follow_up,status,reported_by,players(callsign)').order('occurred_at',{ascending:false}).limit(25);const el=$('#opsIncidentsList');
  if(error){el.innerHTML=`<p class="admin-error">${esc(error.message)} · Apply the V12 migration.</p>`;return;}
  el.innerHTML=(data||[]).length?(data||[]).map(i=>`<article class="ops-record ops-incident"><div><b>${esc(i.incident_type.replaceAll('_',' ').toUpperCase())} · ${esc(i.players?.callsign||'No player linked')}</b><small>${new Date(i.occurred_at).toLocaleString()} · ${esc(i.severity.toUpperCase())} · Reported by ${esc(i.reported_by)}</small><p>${esc(i.summary)}${i.immediate_response?' · Response: '+esc(i.immediate_response):''}${i.follow_up?' · Follow-up: '+esc(i.follow_up):''}</p></div><div class="ops-actions"><select data-incident-status="${i.id}"><option value="open" ${i.status==='open'?'selected':''}>Open</option><option value="under_review" ${i.status==='under_review'?'selected':''}>Under review</option><option value="closed" ${i.status==='closed'?'selected':''}>Closed</option></select><button class="button button-ghost" data-save-incident="${i.id}">UPDATE</button></div></article>`).join(''):'<div class="empty-state">No incidents or near misses recorded.</div>';
  el.querySelectorAll('[data-save-incident]').forEach(b=>b.addEventListener('click',async()=>{const id=b.dataset.saveIncident,status=el.querySelector(`[data-incident-status="${id}"]`).value;const {error}=await db.from('fz_incidents').update({status}).eq('id',id);if(error){msg($('#opsIncidentStatus'),error.message,'error');return;}msg($('#opsIncidentStatus'),'Incident status updated.','success');await Promise.all([loadOpsIncidents(),loadOpsDashboard()])}));
 }
 async function loadOpsCashbook(){
  const month=opsToday().slice(0,7)+'-01';const {data,error}=await db.from('fz_cashbook').select('id,entry_date,entry_type,category,description,amount,payment_method,reference').gte('entry_date',month).order('entry_date',{ascending:false}).limit(100);const el=$('#opsCashbookList');
  if(error){el.innerHTML=`<p class="admin-error">${esc(error.message)} · Apply the V12 migration.</p>`;return;}
  const rows=data||[],income=rows.filter(r=>r.entry_type==='income').reduce((s,r)=>s+Number(r.amount),0),expenses=rows.filter(r=>r.entry_type==='expense').reduce((s,r)=>s+Number(r.amount),0);
  $('#opsCashSummary').innerHTML=`<div><span>MONTH INCOME</span><b>LKR ${income.toLocaleString('en-LK',{maximumFractionDigits:2})}</b></div><div><span>MONTH EXPENSES</span><b>LKR ${expenses.toLocaleString('en-LK',{maximumFractionDigits:2})}</b></div><div><span>NET CASHBOOK</span><b>LKR ${(income-expenses).toLocaleString('en-LK',{maximumFractionDigits:2})}</b></div>`;
  el.innerHTML=rows.length?rows.slice(0,25).map(r=>`<article class="ops-record"><div><b>${esc(r.entry_type.toUpperCase())} · ${esc(r.category)}</b><small>${esc(r.entry_date)} · ${esc(r.payment_method)} · ${esc(r.reference||'No reference')}</small><p>${esc(r.description)}</p></div><strong class="ops-money ${r.entry_type==='expense'?'negative':''}">${r.entry_type==='expense'?'-':'+'} LKR ${Number(r.amount).toFixed(2)}</strong></article>`).join(''):'<div class="empty-state">No cashbook entries for this month.</div>';
 }
 async function loadOpsSocial(){
  const {data,error}=await db.from('fz_social_posts').select('id,scheduled_date,platform,format,content_pillar,caption,status,media_url,published_url,owner_name,notes').order('scheduled_date',{ascending:true,nullsFirst:false}).limit(40);const el=$('#opsSocialList');
  if(error){el.innerHTML=`<p class="admin-error">${esc(error.message)} · Apply the V12 migration.</p>`;return;}
  el.innerHTML=(data||[]).length?(data||[]).map(p=>`<article class="ops-record"><div><b>${esc(p.platform)} · ${esc(p.format)} · ${esc(p.content_pillar)}</b><small>${esc(p.scheduled_date||'Unscheduled')} · ${esc(p.owner_name||'No owner')}</small><p>${esc(p.caption||'No caption draft')}</p>${p.published_url?`<a class="ops-post-link" href="${esc(p.published_url)}" target="_blank" rel="noopener">OPEN PUBLISHED POST ↗</a>`:''}</div><div class="ops-actions"><select data-social-status="${p.id}"><option value="draft" ${p.status==='draft'?'selected':''}>Draft</option><option value="ready" ${p.status==='ready'?'selected':''}>Ready</option><option value="scheduled" ${p.status==='scheduled'?'selected':''}>Scheduled</option><option value="published" ${p.status==='published'?'selected':''}>Published</option></select><button class="button button-ghost" data-save-social="${p.id}">SAVE</button><button class="button button-danger" data-delete-social="${p.id}">DELETE</button></div></article>`).join(''):'<div class="empty-state">No content posts planned yet.</div>';
  el.querySelectorAll('[data-save-social]').forEach(b=>b.addEventListener('click',async()=>{const id=b.dataset.saveSocial,status=el.querySelector(`[data-social-status="${id}"]`).value;const {error}=await db.from('fz_social_posts').update({status,updated_at:new Date().toISOString()}).eq('id',id);if(error){msg($('#opsSocialStatus'),error.message,'error');return;}msg($('#opsSocialStatus'),'Content status updated.','success');await loadOpsSocial()}));
  el.querySelectorAll('[data-delete-social]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Delete this content plan item?'))return;const {error}=await db.from('fz_social_posts').delete().eq('id',b.dataset.deleteSocial);if(error){msg($('#opsSocialStatus'),error.message,'error');return;}await loadOpsSocial()}));
 }
 async function loadOpsAll(){await Promise.all([loadOpsSelects(),loadOpsDashboard(),loadOpsChecklists(),loadOpsSessions(),loadOpsAttendance(),loadOpsEquipment(),loadOpsMaintenance(),loadOpsPoints(),loadOpsIncidents(),loadOpsCashbook(),loadOpsSocial()])}
 $('#opsChecklistType')?.addEventListener('change',renderOpsChecklistItems);
 $('#opsChecklistForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,fd=new FormData(f),items=Array.from(f.querySelectorAll('[data-check-item]')).map(c=>({label:opsTemplates[fd.get('checklist_type')][Number(c.dataset.checkItem)],done:c.checked})),complete=items.every(i=>i.done);if(!fd.get('completed_by')?.trim()){msg($('#opsChecklistStatus'),'Enter the name of the staff member completing the checklist.','error');return;}const {error}=await db.from('fz_checklist_runs').insert({checklist_type:fd.get('checklist_type'),field_id:fd.get('field_id')||null,session_id:fd.get('session_id')||null,run_date:fd.get('run_date'),shift_label:fd.get('shift_label')||'',completed_by:fd.get('completed_by').trim(),checklist_items:items,completion_status:complete?'completed':'incomplete',notes:fd.get('notes')||'',created_by:(await db.auth.getUser()).data.user?.id||null});if(error){msg($('#opsChecklistStatus'),error.message,'error');return;}msg($('#opsChecklistStatus'),complete?'Checklist saved as complete.':'Checklist saved with outstanding checks. Resolve them before opening or starting play.','success');f.reset();$('#opsChecklistDate').value=opsToday();renderOpsChecklistItems();await loadOpsChecklists()});
 $('#opsSessionForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,fd=new FormData(f);if(fd.get('end_time')&&fd.get('start_time')&&fd.get('end_time')<=fd.get('start_time')){msg($('#opsSessionStatus'),'End time must be later than start time.','error');return;}const {error}=await db.from('fz_sessions').insert({session_name:fd.get('session_name').trim(),session_date:fd.get('session_date'),start_time:fd.get('start_time')||null,end_time:fd.get('end_time')||null,field_id:fd.get('field_id')||null,event_id:fd.get('event_id')||null,max_players:Number(fd.get('max_players')),status:fd.get('status'),session_notes:fd.get('session_notes')||'',created_by:(await db.auth.getUser()).data.user?.id||null});if(error){msg($('#opsSessionStatus'),error.message,'error');return;}msg($('#opsSessionStatus'),'Session sheet created.','success');f.reset();$('#opsSessionDate').value=opsToday();await Promise.all([loadOpsSessions(),loadOpsSelects(),loadOpsDashboard()])});
 $('#opsAttendanceForm')?.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const {error}=await db.from('fz_session_attendance').insert({session_id:fd.get('session_id'),player_id:fd.get('player_id'),checked_in:true,notes:fd.get('notes')||'',created_by:(await db.auth.getUser()).data.user?.id||null});if(error){msg($('#opsAttendanceStatus'),error.code==='23505'?'This player is already on the session attendance list.':error.message,'error');return;}msg($('#opsAttendanceStatus'),'Player checked in.','success');e.currentTarget.reset();await loadOpsAttendance()});
 $('#opsEquipmentForm')?.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),payload={asset_code:fd.get('asset_code').trim(),item_name:fd.get('item_name').trim(),category:fd.get('category'),quantity:Number(fd.get('quantity')),condition_status:fd.get('condition_status'),availability_status:fd.get('availability_status'),purchase_date:fd.get('purchase_date')||null,next_service_date:fd.get('next_service_date')||null,notes:fd.get('notes')||''};const {error}=await db.from('fz_equipment').insert(payload);if(error){msg($('#opsEquipmentStatus'),error.message,'error');return;}msg($('#opsEquipmentStatus'),'Equipment asset added.','success');e.currentTarget.reset();await Promise.all([loadOpsEquipment(),loadOpsSelects(),loadOpsDashboard()])});
 $('#opsMaintenanceForm')?.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),payload={equipment_id:fd.get('equipment_id')||null,field_id:fd.get('field_id')||null,task_type:fd.get('task_type'),description:fd.get('description').trim(),findings:fd.get('findings')||'',action_taken:fd.get('action_taken')||'',service_cost:Number(fd.get('service_cost')||0),performed_by:fd.get('performed_by').trim(),next_due_date:fd.get('next_due_date')||null,created_by:(await db.auth.getUser()).data.user?.id||null};const {error}=await db.from('fz_maintenance_logs').insert(payload);if(error){msg($('#opsMaintenanceStatus'),error.message,'error');return;}if(payload.equipment_id){await db.from('fz_equipment').update({last_service_date:opsToday(),next_service_date:payload.next_due_date,updated_at:new Date().toISOString()}).eq('id',payload.equipment_id)}msg($('#opsMaintenanceStatus'),'Maintenance record saved.','success');e.currentTarget.reset();await Promise.all([loadOpsMaintenance(),loadOpsEquipment(),loadOpsDashboard()])});
 $('#opsPointsForm')?.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),points=Number(fd.get('points'));if(!Number.isInteger(points)||points===0||Math.abs(points)>60){msg($('#opsPointsStatus'),'Enter a non-zero whole number between -60 and +60.','error');return;}const {error}=await db.rpc('fz_admin_award_player_points',{p_player_id:fd.get('player_id'),p_points:points,p_category:fd.get('category'),p_reason:fd.get('reason').trim(),p_session_id:fd.get('session_id')||null});if(error){msg($('#opsPointsStatus'),error.message,'error');return;}msg($('#opsPointsStatus'),'Point transaction saved and player total updated.','success');e.currentTarget.reset();await Promise.all([loadOpsPoints(),loadPlayers()])});
 $('#opsIncidentForm')?.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),raw=fd.get('occurred_at'),occurred_at=raw?new Date(raw).toISOString():new Date().toISOString(),payload={occurred_at,incident_type:fd.get('incident_type'),severity:fd.get('severity'),field_id:fd.get('field_id')||null,session_id:fd.get('session_id')||null,player_id:fd.get('player_id')||null,reported_by:fd.get('reported_by').trim(),status:fd.get('status'),summary:fd.get('summary').trim(),immediate_response:fd.get('immediate_response')||'',follow_up:fd.get('follow_up')||'',created_by:(await db.auth.getUser()).data.user?.id||null};const {error}=await db.from('fz_incidents').insert(payload);if(error){msg($('#opsIncidentStatus'),error.message,'error');return;}msg($('#opsIncidentStatus'),'Private incident record saved. Follow-up remains the duty manager’s responsibility.','success');e.currentTarget.reset();$('#opsIncidentWhen').value=opsNowLocal();await Promise.all([loadOpsIncidents(),loadOpsDashboard()])});
