 $('#opsSocialForm')?.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),payload={scheduled_date:fd.get('scheduled_date')||null,platform:fd.get('platform'),format:fd.get('format'),content_pillar:fd.get('content_pillar'),caption:fd.get('caption')||'',media_url:fd.get('media_url')||'',status:fd.get('status'),published_url:fd.get('published_url')||'',owner_name:fd.get('owner_name')||'',notes:fd.get('notes')||'',created_by:(await db.auth.getUser()).data.user?.id||null};const {error}=await db.from('fz_social_posts').insert(payload);if(error){msg($('#opsSocialStatus'),error.message,'error');return;}msg($('#opsSocialStatus'),'Post added to the content planner.','success');e.currentTarget.reset();await loadOpsSocial()});
